import type { QueryHandle } from "@raf-query/react";

import { useDocAccess } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: {
	readonly doc: QueryHandle<typeof docQuery>;
}) => {
	const doc = useDocAccess(docQuery, props.doc);
	return <h1>{doc.title}</h1>;
};

import type { QueryHandle } from "@raf-query/react";
import { Boundary } from "@raf-query/react/boundary";
import { Match } from "effect";

import { useSession } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: {
	readonly doc: QueryHandle<typeof docQuery>;
}) => {
	const doc = useSession(docQuery, props.doc);
	if (Boundary.isUnhandled(doc)) {
		return (
			<p>
				{Match.valueTags(doc.error, {
					DocNotFound: () => "No such doc",
				})}
			</p>
		);
	}
	return <h1>{doc.title}</h1>;
};

import type { QueryHandle } from "@raf-query/react";
import { Boundary } from "@raf-query/react/boundary";
import { Match } from "effect";

import { useDocAccess } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: {
	readonly doc: QueryHandle<typeof docQuery>;
}) => {
	const doc = useDocAccess(docQuery, props.doc);
	if (Boundary.isUnhandled(doc)) {
		return (
			<p>
				{Match.valueTags(doc.error, {
					DocNotFound: () => "No such doc",
					Unauthorized: () => "Sign in",
				})}
			</p>
		);
	}
	return <h1>{doc.title}</h1>;
};

import { Boundary } from "@raf-query/react/boundary";

import { DocAccess } from "../src/boundaries.tsx";

export const [Again, useAgain] = Boundary.catchErrors(DocAccess, {
	fallback: () => <p>Sign in again</p>,
	name: "Again",
	tags: ["Unauthorized"],
});

import { Boundary } from "@raf-query/react/boundary";

import { DocAccess } from "../src/boundaries.tsx";
import { renameDoc } from "../src/queries.ts";

export const Rename = (props: { readonly id: number }) => {
	const run = Boundary.useRun(DocAccess);
	return (
		<button
			onClick={async () => {
				const doc = await run(renameDoc(props.id, "New title"));
				return doc.title;
			}}
			type="button"
		>
			Rename
		</button>
	);
};

import { Boundary } from "@raf-query/react/boundary";
import { Context, Effect } from "effect";

import { DocAccess } from "../src/boundaries.tsx";

class Analytics extends Context.Service<
	Analytics,
	{ readonly views: Effect.Effect<number> }
>()("Analytics") {}

export const Count = () => {
	const run = Boundary.useRun(DocAccess);
	return (
		<button
			onClick={() =>
				run(Effect.flatMap(Analytics, (analytics) => analytics.views))
			}
			type="button"
		>
			Count
		</button>
	);
};

import type { QueryHandle } from "@raf-query/react";
import { Boundary } from "@raf-query/react/boundary";

import { DocAccess, useSession } from "../src/boundaries.tsx";
import { docListQuery, docQuery } from "../src/queries.ts";

export const [Everything, useEverything] = Boundary.catchErrors(DocAccess, {
	fallback: (props) => <p>Doc {props.error.docId} is gone</p>,
	name: "Everything",
	tags: ["DocNotFound"],
});

export const Title = (props: {
	readonly doc: QueryHandle<typeof docQuery>;
}) => {
	const doc = useEverything(docQuery, props.doc);
	return <h1>{doc.title}</h1>;
};

export const Titles = (props: {
	readonly list: QueryHandle<typeof docListQuery>;
}) => {
	const docs = useSession(docListQuery, props.list);
	return (
		<ul>
			{docs.map((doc) => (
				<li key={doc.id}>{doc.title}</li>
			))}
		</ul>
	);
};

import { Boundary } from "@raf-query/react/boundary";

import { DocAccess } from "../src/boundaries.tsx";

export const [Typo, useTypo] = Boundary.catchErrors(DocAccess, {
	fallback: () => <p>Gone</p>,
	name: "Typo",
